import json,os,numpy as np
R=json.load(open('regularized_results.json'));F=json.load(open('fourier_results.json'));D=json.load(open('final_diagnostics.json'));os.makedirs('models',exist_ok=True)
units_note='Physical units were not supplied. Here P denotes the assumed shared logged coordinate unit of `y` and `x1`, U denotes the unknown recorded unit of `x3`, and W denotes the unknown recorded unit of `x4`. `x2` is treated as an angle in radians, inferred from its wrapping, not given by the task.'
common_data='`data/train.csv`, all three trajectories, each with 150 samples at `T_s = 0.2` s. The final fit uses all 447 within-trajectory transitions for the free-running residual and 267 transitions with zero-based within-trajectory index modulo five in {2, 3, 4} for the local regularizer. The latter excludes switch and immediate post-switch samples because diagnostics show actuator-memory effects; no cross-trajectory transition is used. '
common_criterion='Nonlinear least squares on the concatenation of two residual vectors: free-running coordinate errors in `y` and `x1` and wrapped angle errors multiplied by `0.25` P/rad; and local increment errors multiplied by `100`, a dimensionless regularization weight. Thus the local sum of squares has relative weight `10000`. The local coordinate errors have units P and local angle errors are multiplied by `0.25` P/rad. Free-running residuals include all samples after the initial state. Local residuals use block-interior transitions only. The coordinate criterion addresses accumulated trajectory errors; the local penalty discourages spurious nonlinear response curves introduced to explain persistent disturbances and unavailable input history. The angle weighting is a chosen geometric scale, not a known physical length. The regularization weight was selected using leave-one-trajectory-out `y` prediction errors among `5`, `20`, `100`, and local-only fits for rigid maps, and `20`, `100`, and `300` for the Fourier map; it is not an estimated model constant.'
common_limits='The interpretation is inferred, not a known description of this system. Recorded units, hardware, actuator state, noise model, and input behavior outside the observed range are unknown. No previous inputs may enter the required expressions, so switch transients cannot be represented exactly. Residual autocorrelation and persistent block disturbances remain. Long-horizon heading bias accumulates into coordinate error, and validation contains only three trajectories; model choice is consequently uncertain. Prefix-to-tail validation is materially worse than whole-trajectory holdout. The map is intended only near the observed input and state coverage, not arbitrary large inputs. '
common_origin='Before fitting I listed affine, polynomial, and bounded/periodic model families. Ordinary least squares affine and polynomial maps of degrees one through three were explored on within-trajectory increments; their poor trajectory-held-out increment behavior, and angle wrapping, motivated periodic coordinates. A bicycle-like `x3*x4` angle response was rejected after comparison with an independent `x4` response. Body-frame projection showed that midpoint-angle integration greatly reduced lateral residuals. I then fitted Euler and midpoint linear maps, midpoint cubic, signed-power and dead-zone maps, and a cubic exact-arc map by free-running nonlinear least squares. Residuals showed strong switch transients and serial dependence rather than evidence for coordinate-dependent forces; adding coordinate and heading predictors to scalar input regressions did not reliably improve held-out local errors. This motivated the interior-increment regularizer rather than extra state-dependent terms. No symbolic-regression package or random search was used. '
def fmt(v):return format(v,'.16g')
def describe_metrics(label):
 d=D[label];return ('On all training trajectories the free-running `y` RMSE is `'+fmt(d['train_rmse'][0])+'` P. Leave-one-trajectory-out `y` RMSE values for held-out trajectories one, two, and three are `'+str(d['loo_rmse'][0][0])+'`, `'+str(d['loo_rmse'][1][0])+'`, and `'+str(d['loo_rmse'][2][0])+'` P, respectively; their equal-size aggregate is `'+fmt(d['aggregate_loo_y_rmse'])+'` P. Refitting on the first 100 samples of every trajectory and continuing free runs from the original initial states gives final-50-sample `y` RMSE `'+fmt(d['tail50_rmse'][0])+'` P. All validation uses only the training file, not hidden test data. On all 447 transitions the one-step `y` RMSE is `'+fmt(d['one_step_rmse'][0])+'` P; on the 90 switch-step transitions it is `'+fmt(d['phase0_one_step_rmse'][0])+'` P, versus `'+fmt(d['interior_one_step_rmse'][0])+'` P on the 267 interior transitions. Adjacent one-step `y` residual correlation is `'+fmt(d['lag1_one_step_correlation'][0])+'`, dimensionless, computed only within trajectories. The block phase is used only to choose fitting rows, never as an expression argument. ')
def save(label,expr,params,method,family,interpretation,origin):
 obj={'expressions':expr,'parameters':params,'estimation':{'criterion':common_criterion,'data':common_data,'method':method+' Reference: SciPy API documentation, least_squares, checked directly; NumPy API documentation, numpy.linalg.lstsq, checked directly. SciPy documents the trust-region reflective bounded least-squares method; NumPy documents its direct least-squares solve. Defaults used were linear loss and a two-point finite-difference Jacobian for the nonlinear solve.','script':'reproduce_submission.py'},'discussion':{'family':family,'interpretation':units_note+' '+interpretation,'origin':common_origin+origin,'limitations':common_limits+describe_metrics(label)}}
 json.dump(obj,open('models/'+label+'.json','w'),indent=2)
def row(name,val,unit,description):return {'name':name,'value':float(val),'unit':unit,'type':'fitted','description':description}
for label,key in [('RigidDeadzone','deadzone_mid_100'),('RigidPower','power_mid_100')]:
 r=R[key];p=r['parameters'];names=['sb','sv','hb','hg','hd' if label=='RigidDeadzone' else 'hp'];h='hb + hg*sign(x4)*Max(Abs(x4)-hd, 0)' if label=='RigidDeadzone' else 'hb + hg*sign(x4)*Abs(x4)**hp';s='sb + sv*x3'
 expr={'y_next':f'y + ({s})*cos(x2 + 0.5*({h}))','x1_next':f'x1 + ({s})*sin(x2 + 0.5*({h}))','x2_next':f'atan2(sin(x2 + ({h})), cos(x2 + ({h})))'}
 params=[row('sb',p[0],'P','Intercept in signed forward step `sb + sv*x3`; P is the assumed shared coordinate unit, unknown physically.'),row('sv',p[1],'P/U','Slope of signed forward step with recorded input `x3`; U is its unknown unit.'),row('hb',p[2],'rad','Input-independent angle increment; radian interpretation is assumed from wrapping.'),row('hg',p[3],'rad/W' if label=='RigidDeadzone' else 'rad/(W**hp)','Scale of the nonlinear angle response to recorded input `x4`; W is its unknown unit, and `hp` is the fitted exponent for the signed-power map.')]
 if label=='RigidDeadzone':params.append(row('hd',p[4],'W','Fitted threshold in `sign(x4)*Max(Abs(x4)-hd, 0)`; this is an empirical dead zone, not established actuator friction.'))
 else:params.append(row('hp',p[4],'-','Fitted exponent in `sign(x4)*Abs(x4)**hp`, a nonlinear response to the recorded input numerical scale.'))
 start='['+', '.join(fmt(x) for x in r['starting'])+']';bds='`-0.02 <= sb <= 0.02` P, `0 <= sv <= 0.4` P/U, `-0.05 <= hb <= 0.05` rad, and '+('`0 <= hg <= 0.5` rad/W and `0 <= hd <= 0.3` W.' if label=='RigidDeadzone' else '`0 <= hg <= 0.5` rad/(W**hp) and `0.3 <= hp <= 3`.')
 method='All five parameters were estimated jointly by the trust-region reflective nonlinear least-squares algorithm in `scipy.optimize.least_squares`, as implemented by `fit_regularized.fit`, with the family `'+r['family']+'` and the multiplier `100`. This algorithm handles the chosen parameter bounds and a nonlinear multi-step residual, unlike ordinary linear least squares. The starting vector in parameter order `'+', '.join(names)+'` was `'+start+'`; its entries have the corresponding parameter units. These rounded starts were motivated by preliminary block-interior input regressions (a forward gain near one sixth and a small angle offset), not copied fitted values from another submitted candidate. Bounds were '+bds+' They keep the response in a modest range seen in training and prevent unconstrained nonlinear gains; they are assumptions rather than known physical bounds. Maximum function evaluations were `3000`, and `ftol = xtol = gtol = 1e-10`, dimensionless convergence tolerances. There is no random seed because the procedure is deterministic. Starting values, the data selection, objective, and settings are reproduced by `fit_regularized.py`; `reproduce_submission.py` reruns this fit and writes the candidate. Other fits were used only for structural comparison and regularization selection; no fitted parameter was held over or fixed.'
 family='Discrete-time planar kinematic (unicycle-type) map with midpoint integration and '+('a static dead-zone input nonlinearity, also called a Hammerstein-type input block.' if label=='RigidDeadzone' else 'a static signed-power input nonlinearity.')+' The terminology describes mathematical structure only; no specific vehicle is claimed. A related reference is R. M. Murray, Z. X. Li, and S. S. Sastry, A Mathematical Introduction to Robotic Manipulation, CRC Press, 1994. Book authorship and publication were verified on the author-hosted MLS archive; the nonholonomic-kinematics association is recalled from memory and its chapter text was not checked. The empirical input-response function and discrete midpoint map are choices made here, not equations attributed to that book.'
 interp='The signed forward step is `sb + sv*x3`: `sb` adds a constant offset and `sv*x3` adds a linear response. The angle step is `'+h+'`: `hb` is drift and the remaining term is '+('zero inside the fitted input dead zone and affine in input magnitude outside it.' if label=='RigidDeadzone' else 'odd in `x4` with curvature controlled by `hp`; the sign operator preserves direction.')+' Position increments use `cos(x2 + 0.5*('+h+'))` and `sin(x2 + 0.5*('+h+'))`, tying the two coordinates to the same forward step and midpoint direction. The factor `0.5` defines midpoint integration. The expression `atan2(sin(x2 + ('+h+')), cos(x2 + ('+h+')))` wraps the updated angle to the principal branch. No attraction to coordinate zero or coordinate-dependent force is assumed.'
 origin='The selected '+('dead-zone threshold' if label=='RigidDeadzone' else 'signed-power exponent')+' is an empirical input-response choice suggested by scalar block-interior regressions. It is not physical knowledge. I retained this candidate because '+('it achieves nearly the best trajectory-held-out scored-output error with only five coefficients.' if label=='RigidDeadzone' else 'it offers a continuous curved response outside zero without an explicit dead-zone threshold, with reasonable held-out performance.')
 save(label,expr,params,method,family,interp,origin)
r=F['100'];p=np.array(r['parameters']);features=['1','x3*cos(x2)','x3*sin(x2)','cos(x2)','sin(x2)','x3*x4*cos(x2)','x3*x4*sin(x2)'];params=[];terms=[[],[]]
for i,term in enumerate(features):
 for j,prefix in enumerate(['a','b']):
  name=prefix+str(i);terms[j].append(name if i==0 else name+'*('+term+')');unit=['P','P/U','P/U','P','P','P/(U*W)','P/(U*W)'][i];params.append(row(name,p[2*i+j],unit,'Coefficient of `'+term+'` in the increment of `'+(['y','x1'][j])+'`; P, U and W are the unknown recorded units defined in the interpretation.'))
params.extend([row('hb',p[-3],'rad','Input-independent angle increment.'),row('hg',p[-2],'rad/W','Gain of the odd dead-zone response to `x4`.'),row('hd',p[-1],'W','Empirical dead-zone threshold of recorded input `x4`.')]);h='hb + hg*sign(x4)*Max(Abs(x4)-hd, 0)';expr={'y_next':'y + '+' + '.join(terms[0]),'x1_next':'x1 + '+' + '.join(terms[1]),'x2_next':f'atan2(sin(x2 + ({h})), cos(x2 + ({h})))'}
start='['+', '.join(fmt(v) for v in r['starting'])+']';order=', '.join(q['name'] for q in params)
method='All 17 parameters were estimated jointly by trust-region reflective nonlinear least squares using `scipy.optimize.least_squares` in `fit_fourier.fit` with multiplier `100`; this is appropriate for the nonlinear accumulated-angle residual and parameter bounds. Initialization first computes the 14 coordinate-increment coefficients by ordinary least squares using `numpy.linalg.lstsq` on all 447 within-trajectory measured transitions (no starting values needed for this linear subproblem), then appends angle starts `hb = 0` rad, `hg = 0.1667` rad/W, and `hd = 0.09` W, motivated by interior scalar regressions. These initial coordinate coefficients are not held fixed: the joint fit estimates all coefficients again under the stated criterion. The complete joint starting vector in parameter order `'+order+'` is `'+start+'`, with each entry carrying its parameter unit. Coordinate coefficients are each bounded between `-0.5` and `0.5` in their listed units, `-0.05 <= hb <= 0.05` rad, `0 <= hg <= 0.5` rad/W, and `0 <= hd <= 0.3` W. These broad bounds are chosen to prevent extreme empirical gains, not known physical limits. The maximum function evaluations are `3000`, with `ftol = xtol = gtol = 1e-10`, dimensionless convergence tolerances. No random seed applies: the computation is deterministic. `fit_fourier.py` contains the objective and initialization; `reproduce_submission.py` reruns the fit and writes this candidate. No coefficient is copied or held over from a submitted rigid map.'
family='Additive first-harmonic Fourier state map with bilinear input features, integrator state updates, and a separate static dead-zone angle-response map. Unlike the rigid kinematic map, its two coordinate increments have independent fitted coefficients and are not constrained to a shared forward step or midpoint angle. This candidate is defined by its explicit regression library rather than attributed to a particular published system equation.'
interpretation='For each coordinate, the feature `1` supplies a constant increment; `x3*cos(x2)` and `x3*sin(x2)` give first-harmonic input-direction coupling; `cos(x2)` and `sin(x2)` allow direction-dependent offsets; `x3*x4*cos(x2)` and `x3*x4*sin(x2)` allow first-order turning-input corrections. Their coefficients are independent in the two coordinates, so small cross-axis effects, anisotropy, and lateral increments are permitted mathematically, without claiming a physical cause. The angle step `'+h+'` supplies offset drift and an odd dead-zone response, and `atan2(sin(x2 + ('+h+')), cos(x2 + ('+h+')))` wraps the next angle. The current positions `y` and `x1` enter with identity coefficients, preserving translation invariance.'
origin='The Fourier feature library was hand-constructed from the observed directional alignment and a first-order expansion of midpoint direction: its turning corrections use `x3*x4*cos(x2)` and `x3*x4*sin(x2)`. An unrestricted first-harmonic map was tested to check whether tying both coordinate increments to one scalar forward step was too restrictive. Features were not selected by genetic programming or sparse thresholding. The dead-zone angle form came from the earlier empirical input-response comparison; all its values were refitted in this candidate. I retained this family because it improves scored-output trajectory holdout while allowing a modest independent cross-axis response.'
save('FourierMap',expr,params,method,family,interpretation,origin)
pool={'order':['FourierMap','RigidDeadzone','RigidPower'],'recommended':'FourierMap','reason':'The independent Fourier state map has the lowest aggregate leave-one-trajectory-out scored `y` RMSE among the retained families: `0.08581916496554522` in logged `y` units on `data/train.csv`, versus `0.08971175638571534` for the five-parameter rigid dead-zone map and `0.10647703014936342` for the signed-power map. It also has lower full-training free-running coordinate error than the other retained maps. This is a small advantage, not proof of test superiority: it uses more coefficients, and prefix-to-tail validation gives `0.1982659017905261` in logged `y` units, worse than the simpler alternatives. The rigid dead-zone map is retained as the parsimonious fallback. All candidates omit input history and leave substantial switch residuals.'}
json.dump(pool,open('models/pool.json','w'),indent=2)
print('Exported',pool['order'])
